          SessionYardState.Open, SessionYardCommand.Lower, SessionYardState.Closed ]

    /// Every branching transition as (from, command, the targets its selector may pick).
    let branching : (SessionYardState * SessionYardCommand * SessionYardState list) list =
        [ SessionYardState.Closed, SessionYardCommand.Raise, [ SessionYardState.Jammed; SessionYardState.Open ] ]

    /// The fixed target of a single-target transition, or None where the plan lists none; a
    /// branching transition's target is picked in `next`. Every (state, command) pair is listed;
    /// there is no catch-all.
    let target (state: SessionYardState) (command: SessionYardCommand) : SessionYardState option =
        match state, command with
        | SessionYardState.Closed, SessionYardCommand.Lower -> None
        | SessionYardState.Closed, SessionYardCommand.Raise -> None
        | SessionYardState.Closed, SessionYardCommand.Reset -> None
        | SessionYardState.Jammed, SessionYardCommand.Lower -> None
        | SessionYardState.Jammed, SessionYardCommand.Raise -> None
        | SessionYardState.Jammed, SessionYardCommand.Reset -> Some SessionYardState.Closed
        | SessionYardState.Open, SessionYardCommand.Lower -> Some SessionYardState.Closed
        | SessionYardState.Open, SessionYardCommand.Raise -> None
        | SessionYardState.Open, SessionYardCommand.Reset -> None

    /// The target of a command: fixed for a single-target transition, picked by the handwritten
    /// selector for a branching one, None where the command is not legal. Every pair is listed;
    /// there is no catch-all.
    let next (rules: SessionYardRules) (state: SessionYardState) (command: SessionYardCommand) : SessionYardState option =
        match state, command with
        | SessionYardState.Closed, SessionYardCommand.Lower -> target state command
        | SessionYardState.Closed, SessionYardCommand.Raise -> Some(match rules.Select_Closed_Raise () with SessionYardBranch_Closed_Raise.Jammed -> SessionYardState.Jammed | SessionYardBranch_Closed_Raise.Open -> SessionYardState.Open)
