        | SessionYardState.Jammed, SessionYardCommand.Lower -> target state command
        | SessionYardState.Jammed, SessionYardCommand.Raise -> target state command
        | SessionYardState.Jammed, SessionYardCommand.Reset -> target state command
        | SessionYardState.Open, SessionYardCommand.Lower -> target state command
        | SessionYardState.Open, SessionYardCommand.Raise -> target state command
        | SessionYardState.Open, SessionYardCommand.Reset -> target state command

    /// The guards a legal command must satisfy in a state.
    let guards (state: SessionYardState) (command: SessionYardCommand) : SessionYardGuard list =
