        | SessionYardState.Closed, SessionYardCommand.Reset -> []
        | SessionYardState.Jammed, SessionYardCommand.Lower -> []
        | SessionYardState.Jammed, SessionYardCommand.Raise -> []
        | SessionYardState.Jammed, SessionYardCommand.Reset -> []
        | SessionYardState.Open, SessionYardCommand.Lower -> [ SessionYardGuard.PathClear ]
        | SessionYardState.Open, SessionYardCommand.Raise -> []
        | SessionYardState.Open, SessionYardCommand.Reset -> []

    /// Decides one command. Refusal is data; nothing is applied or performed here.
    let decide (rules: SessionYardRules) (state: SessionYardState) (command: SessionYardCommand) : Result<SessionYardDecision, SessionYardRefusal> =
        match next rules state command with
        | None -> Error(SessionYardRefusal.InvalidTransition(state, command))
        | Some next ->
