        | SessionYardState.Closed, SessionYardCommand.Reset -> Some SessionYardRefusalCode.NotAccepted
        | SessionYardState.Jammed, SessionYardCommand.Lower -> Some SessionYardRefusalCode.NotAccepted
        | SessionYardState.Jammed, SessionYardCommand.Raise -> Some SessionYardRefusalCode.NotAccepted
        | SessionYardState.Jammed, SessionYardCommand.Reset -> None
        | SessionYardState.Open, SessionYardCommand.Lower -> None
        | SessionYardState.Open, SessionYardCommand.Raise -> Some SessionYardRefusalCode.AlreadyOpen
        | SessionYardState.Open, SessionYardCommand.Reset -> Some SessionYardRefusalCode.NotAccepted

